SET NOCOUNT ON;
SELECT DB_NAME() AS DatabaseName;
SELECT Id, CardNumber, NormalizedCardNumber, Provider, IsDeleted FROM app.FuelCards WHERE NormalizedCardNumber=N'BW502' OR CardNumber=N'BW502';
SELECT s.name AS SchemaName,t.name AS TableName,c.name AS ColumnName,ty.name AS DataType FROM sys.tables t JOIN sys.schemas s ON s.schema_id=t.schema_id JOIN sys.columns c ON c.object_id=t.object_id JOIN sys.types ty ON ty.user_type_id=c.user_type_id WHERE t.name LIKE N'%Fuel%' ORDER BY s.name,t.name,c.column_id;
SELECT fk.name AS ForeignKeyName,ps.name AS ChildSchema,pt.name AS ChildTable,pc.name AS ChildColumn,rs.name AS ParentSchema,rt.name AS ParentTable,rc.name AS ParentColumn,fk.delete_referential_action_desc AS DeleteAction FROM sys.foreign_keys fk JOIN sys.foreign_key_columns fc ON fc.constraint_object_id=fk.object_id JOIN sys.tables pt ON pt.object_id=fk.parent_object_id JOIN sys.schemas ps ON ps.schema_id=pt.schema_id JOIN sys.columns pc ON pc.object_id=pt.object_id AND pc.column_id=fc.parent_column_id JOIN sys.tables rt ON rt.object_id=fk.referenced_object_id JOIN sys.schemas rs ON rs.schema_id=rt.schema_id JOIN sys.columns rc ON rc.object_id=rt.object_id AND rc.column_id=fc.referenced_column_id WHERE rt.name LIKE N'%Fuel%' ORDER BY rt.name,pt.name;
